class Robot(private val width:Int,private val height:Int){private val perimeter=2*(width+height)-4;private var progress=0;private var moved=false;fun step(num:Int){progress=(progress+num%perimeter)%perimeter;moved=true}fun getPos():IntArray{val east=width-1;val north=east+height-1;val west=north+width-1;return when{progress<=east->intArrayOf(progress,0);progress<=north->intArrayOf(width-1,progress-east);progress<=west->intArrayOf(width-1-(progress-north),height-1);else->intArrayOf(0,height-1-(progress-west))}}fun getDir():String{val east=width-1;val north=east+height-1;val west=north+width-1;return when{progress==0->if(moved)"South" else "East";progress<=east->"East";progress<=north->"North";progress<=west->"West";else->"South"}}}
